/// The ids a `Stat` third may carry — `addStat`'s additive arms (0x04 is a no-op,
/// 0x13.. are mode switches). The hook refuses anything else.
pub const fn guest_stat(id: u8) -> bool {
    matches!(id, 0x02 | 0x03 | 0x05..=0x12)
}
